INSERT INTO knowledge_items(id,topic,title,content,source_url,version,review_status) VALUES
('cold-care','感冒鼻咽','感冒自我护理资料','休息并注意补充水分。记录呼吸、发热、持续时间及是否加重；出现明显异常或持续不改善时寻求医疗帮助。具体药品需核对产品说明、适用人群和重复成分，不由本条生成剂量。','https://www.nhs.uk/conditions/common-cold/','2026-10-19','reference'),
('skin-care','皮肤不适','皮肤不适与湿疹参考资料','避免刺激，记录瘙痒、疼痛、渗出、范围和变化。外观相似不等于确诊；明显疼痛、肿胀、发热或渗液等变化需进一步求助。外用激素需核对具体产品、强度、部位及既有指导，不以统一天数决定停用。','https://www.nhs.uk/conditions/atopic-eczema/','2026-10-19','reference'),
('allergy-care','轻度过敏','花粉与过敏参考资料','记录鼻眼症状、接触环境与时间；根据实际环境减少相关刺激。不能仅凭季节判断过敏。出现呼吸或全身严重异常时优先求助，不继续普通护理问答。','https://www.nhs.uk/conditions/hay-fever/','2026-10-19','reference'),
('digestive-care','胃肠不适','胃肠不适参考资料','记录呕吐、排便变化、持续时间和能否补水，留意脱水表现。能否继续自主处理取决于具体变化和适用条件，不将胃肠不适直接诊断为感染。','https://www.nhs.uk/conditions/diarrhoea-and-vomiting/','2026-10-19','reference'),
('pain-care','轻微疼痛','头痛参考资料','记录疼痛发生时间、程度、伴随表现和实际使用的产品。突然出现或异常严重的疼痛及其他异常变化需要及时求助，不能依赖聊天排除疾病。','https://www.nhs.uk/conditions/headaches/','2026-10-19','reference'),
('history-thirst','历史线索','口渴与排尿变化参考资料','持续口渴、排尿增多和非主动体重下降是值得进一步核实的相关表现。若个人记录中明确存在这些变化，可建议补充持续时间、检查资料并就医核实；症状匹配不等于诊断，缺少症状也不排除疾病。','https://www.nhs.uk/conditions/type-2-diabetes/symptoms/','2026-10-19','reference');
